package com.renatus;

import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.Counter;

/** On-screen counter of splits waiting for the player's confirmation. */
class PendingSplitsInfoBox extends Counter
{
	PendingSplitsInfoBox(BufferedImage image, Plugin plugin, int count)
	{
		super(image, plugin, count);
	}

	@Override
	public String getTooltip()
	{
		int count = getCount();
		return "Renatus: " + count + (count == 1 ? " split" : " splits") + " waiting for your confirmation in Discord";
	}
}

package com.renatus;

import com.google.gson.FieldNamingPolicy;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import com.renatus.model.ClanSummary;
import com.renatus.model.LeaderboardEntry;
import com.renatus.model.PlayerProfile;
import com.renatus.model.Split;
import com.renatus.model.SplitResponse;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.List;
import java.util.function.Consumer;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the read-only plugin API (/api/plugin/v1).
 */
@Slf4j
@Singleton
public class RenatusApiClient
{
	private static final Type LEADERBOARD_TYPE = new TypeToken<List<LeaderboardEntry>>() {}.getType();
	private static final Type SPLITS_TYPE = new TypeToken<List<Split>>() {}.getType();
	private static final Type NAMES_TYPE = new TypeToken<List<String>>() {}.getType();
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String USER_AGENT = "RenatusPvMPlugin/" + RenatusPlugin.getPluginVersion();
	private static final String BASE_URL = "https://renatus-pvm.com";

	private static final HttpUrl API_ROOT = HttpUrl.get(BASE_URL).newBuilder()
		.addPathSegment("api")
		.addPathSegment("plugin")
		.addPathSegment("v1")
		.build();

	private static final long DEFAULT_RETRY_AFTER_SECONDS = 30;

	private static final CacheControl NO_STORE = new CacheControl.Builder().noStore().build();


	private volatile long rateLimitedUntil;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final RenatusConfig config;

	@Inject
	RenatusApiClient(OkHttpClient httpClient, Gson gson, RenatusConfig config)
	{
		this.httpClient = httpClient;
		this.gson = gson.newBuilder()
			.setFieldNamingPolicy(FieldNamingPolicy.LOWER_CASE_WITH_UNDERSCORES)
			.create();
		this.config = config;
	}

	enum SetupState
	{
		DISABLED,
		NO_KEY,
		READY,
	}

	SetupState setupState()
	{
		if (!config.enableApi())
		{
			return SetupState.DISABLED;
		}
		if (config.apiKey().trim().isEmpty())
		{
			return SetupState.NO_KEY;
		}
		return SetupState.READY;
	}

	public interface ResultCallback<T>
	{
		void onResult(@Nullable T result);
	}

	/**
	 * @return the API root ({@code <site>/api/plugin/v1/}), or
	 * null unless {@link #setupState()} is READY
	 */
	@Nullable
	HttpUrl apiRoot()
	{
		if (setupState() != SetupState.READY)
		{
			return null;
		}
		return API_ROOT;
	}

	/** The API key owner's own profile, including splits waiting on them. */
	public void fetchMe(ResultCallback<PlayerProfile> onResult, Consumer<String> onError)
	{
		get(b -> b.addPathSegment("me"), PlayerProfile.class, onResult, onError);
	}

	public void fetchPlayer(String rsn, ResultCallback<PlayerProfile> onResult, Consumer<String> onError)
	{
		get(b -> b.addPathSegment("player").addPathSegment(rsn), PlayerProfile.class, onResult, onError);
	}

	public void fetchClan(ResultCallback<ClanSummary> onResult, Consumer<String> onError)
	{
		get(b -> b.addPathSegment("clan"), ClanSummary.class, onResult, onError);
	}

	public void fetchLeaderboard(int limit, ResultCallback<List<LeaderboardEntry>> onResult, Consumer<String> onError)
	{
		get(b -> b.addPathSegment("leaderboard").addQueryParameter("limit", Integer.toString(limit)),
			LEADERBOARD_TYPE, onResult, onError);
	}

	public void fetchRecentSplits(int limit, ResultCallback<List<Split>> onResult, Consumer<String> onError)
	{
		get(b -> b.addPathSegment("recent-splits").addQueryParameter("limit", Integer.toString(limit)),
			SPLITS_TYPE, onResult, onError);
	}

	/** RSNs of every clan members. */
	public void fetchMembers(ResultCallback<List<String>> onResult, Consumer<String> onError)
	{
		get(b -> b.addPathSegment("members"), NAMES_TYPE, onResult, onError);
	}

	/**
	 * Confirms (approve) or denies a split the key's owner was tagged in.
	 * Errors carry the server's message (e.g."You have already responded
	 * to this split.").
	 */
	public void respondToSplit(String code, boolean approve, ResultCallback<SplitResponse> onResult, Consumer<String> onError)
	{
		JsonObject json = new JsonObject();
		json.addProperty("approve", approve);
		RequestBody body = RequestBody.create(JSON, json.toString());
		send(b -> b.addPathSegment("splits").addPathSegment(code).addPathSegment("respond"),
			r -> r.post(body), SplitResponse.class, false, onResult, onError);
	}

	private <T> void get(Consumer<HttpUrl.Builder> path, Type type, ResultCallback<T> onResult, Consumer<String> onError)
	{
		send(path, Request.Builder::get, type, true, onResult, onError);
	}

	/**
	 * @param notFoundIsNull whether a 404 is a normal "no such thing" result
	 *                       (lookups) rather than an error (actions)
	 */
	private <T> void send(Consumer<HttpUrl.Builder> path, Consumer<Request.Builder> method, Type type,
		boolean notFoundIsNull, ResultCallback<T> onResult, Consumer<String> onError)
	{
		HttpUrl root = apiRoot();
		if (root == null)
		{
			onError.accept("Clan server not configured");
			return;
		}
		long waitSeconds = rateLimitSecondsLeft();
		if (waitSeconds > 0)
		{
			onError.accept(rateLimitMessage(waitSeconds));
			return;
		}

		HttpUrl.Builder builder = root.newBuilder();
		path.accept(builder);
		Request.Builder requestBuilder = new Request.Builder()
			.url(builder.build())
			.header("User-Agent", USER_AGENT)
			.header("Authorization", "Bearer " + config.apiKey().trim())
			// Per-user, authenticated data: keep it out of RuneLite's shared disk cache.
			.cacheControl(NO_STORE);
		method.accept(requestBuilder);
		Request request = requestBuilder.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				log.debug("Renatus API request to {} failed", request.url(), e);
				onError.accept("Couldn't reach the clan server");
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				String raw = null;
				try (ResponseBody body = response.body())
				{
					if (response.code() == 401)
					{
						onError.accept("API key not accepted. Run /get-api-key in Discord and paste the new key into the plugin config.");
						return;
					}
					if (response.code() == 429)
					{
						long retryAfter = retryAfterSeconds(response);
						rateLimitedUntil = System.currentTimeMillis() + retryAfter * 1000;
						log.debug("Renatus API rate limited; retrying after {}s", retryAfter);
						onError.accept(rateLimitMessage(retryAfter));
						return;
					}
					if (response.code() == 404 && notFoundIsNull)
					{
						onResult.onResult(null);
						return;
					}
					if (!response.isSuccessful() || body == null)
					{
						log.warn("Renatus API {} returned HTTP {}", request.url(), response.code());
						onError.accept(errorMessage(body, response.code()));
						return;
					}
					raw = body.string();
					T parsed = gson.fromJson(raw, type);
					onResult.onResult(parsed);
				}
				catch (JsonParseException e)
				{
					log.warn("Renatus API {} returned an unreadable response (HTTP {}, Content-Type {}): {}",
						request.url(), response.code(), response.header("Content-Type"), snippet(raw), e);
					onError.accept("Unexpected response from the clan server");
				}
				catch (IOException e)
				{
					log.debug("Renatus API {} response body couldn't be read", request.url(), e);
					onError.accept("Couldn't reach the clan server");
				}
			}
		});
	}

	/** Rate limited us and Retry-After hasn't passed yet. */
	boolean isRateLimited()
	{
		return rateLimitSecondsLeft() > 0;
	}

	private long rateLimitSecondsLeft()
	{
		long millisLeft = rateLimitedUntil - System.currentTimeMillis();
		return millisLeft > 0 ? (millisLeft + 999) / 1000 : 0;
	}

	private static String rateLimitMessage(long seconds)
	{
		return "Too many requests to the clan server. Try again in " + seconds + "s.";
	}

	/** First part of a response body, for debug logs. */
	private static String snippet(@Nullable String raw)
	{
		if (raw == null)
		{
			return "<no body>";
		}
		return raw.length() > 500 ? raw.substring(0, 500) + "..." : raw;
	}

	/** Retry-After */
	private static long retryAfterSeconds(Response response)
	{
		String header = response.header("Retry-After");
		if (header != null)
		{
			try
			{
				return Math.max(1, Long.parseLong(header.trim()));
			}
			catch (NumberFormatException e)
			{
				log.debug("Unexpected Retry-After header: {}", header);
			}
		}
		return DEFAULT_RETRY_AFTER_SECONDS;
	}

	/** The server's {"error": "..."} message if it sent one, else a generic one. */
	private String errorMessage(ResponseBody body, int code)
	{
		if (body != null)
		{
			try
			{
				JsonObject json = gson.fromJson(body.charStream(), JsonObject.class);
				if (json != null && json.has("error") && json.get("error").isJsonPrimitive())
				{
					return json.get("error").getAsString();
				}
			}
			catch (JsonParseException e)
			{
				log.debug("Renatus API error body wasn't JSON", e);
			}
		}
		return "Clan server error (HTTP " + code + ")";
	}
}

package com.renatus;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(RenatusConfig.GROUP)
public interface RenatusConfig extends Config
{
	String GROUP = "renatus-pvm";

	@ConfigItem(
		keyName = "enableApi",
		name = "Connect to clan server",
		description = "Fetch your rank, splits and the clan leaderboard from the Renatus clan server",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 0
	)
	default boolean enableApi()
	{
		return false;
	}

	@ConfigItem(
		keyName = "apiKey",
		name = "API key",
		description = "Your personal key: run /get-api-key in the Renatus Discord and paste it here",
		secret = true,
		position = 1
	)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(
		keyName = "pendingReminder",
		name = "Pending split reminder",
		description = "On login, remind you of splits you've been tagged in but haven't confirmed in Discord yet",
		position = 3
	)
	default boolean pendingReminder()
	{
		return true;
	}

	@ConfigItem(
		keyName = "newSplitAlert",
		name = "New split alert",
		description = "Chat message and notification when someone tags you in a new split to confirm (checked every 5 minutes while logged in)",
		position = 4
	)
	default boolean newSplitAlert()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pendingInfoBox",
		name = "Pending split info box",
		description = "Show an info box with the number of splits waiting for your confirmation",
		position = 5
	)
	default boolean pendingInfoBox()
	{
		return true;
	}

	@Range(min = 5, max = 50)
	@ConfigItem(
		keyName = "leaderboardSize",
		name = "Leaderboard size",
		description = "How many members to show on the leaderboard tab",
		position = 6
	)
	default int leaderboardSize()
	{
		return 10;
	}
}

package com.renatus;

import com.renatus.model.ClanSummary;
import com.renatus.model.LeaderboardEntry;
import com.renatus.model.PlayerProfile;
import com.renatus.model.Rank;
import com.renatus.model.Split;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;
import net.runelite.client.util.QuantityFormatter;

/**
 * Side panel. Every public method must be called on the Swing EDT.
 */
class RenatusPanel extends PluginPanel
{
	private static final Color GOLD = new Color(255, 200, 60);
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color PENDING_RED = new Color(230, 70, 70);

	private final ItemManager itemManager;

	/** Minimum gap between manual refreshes, so the button can't be spammed. */
	private static final int REFRESH_COOLDOWN_SECONDS = 30;

	private final JButton refreshButton = new JButton(refreshLabel(0));
	private Timer cooldownTimer;
	private int cooldownLeft;
	private final JLabel messageLabel = new JLabel();
	private final IconTextField searchField = new IconTextField();
	private final JPanel profilePanel = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
	private final JPanel clanPanel = new JPanel(new GridLayout(2, 2, 4, 4));
	private final JPanel leaderboardList = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
	private final JPanel recentList = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
	private final JPanel ranksList = new JPanel(new DynamicGridLayout(0, 1, 0, 2));

	private static final int MAX_SUGGESTIONS = 8;
	private final JPanel suggestionsPanel = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
	private final List<JLabel> suggestionLabels = new ArrayList<>();
	private final List<String> suggestions = new ArrayList<>();
	private List<String> members = Collections.emptyList();
	private int selectedSuggestion = -1;
	// Set while the panel itself changes the search text, so that doesn't reopen the dropdown.
	private boolean updatingSearch;

	private RenatusPlugin plugin;

	// What the profile card shows: our own profile unless a lookup is open.
	private PlayerProfile ownProfile;
	private boolean ownLoaded;
	private String lookupName;
	private PlayerProfile lookupProfile;
	private List<Rank> ranks = Collections.emptyList();
	// Profile splits whose participant list is open; kept across refreshes.
	private final Set<String> expandedSplits = new HashSet<>();
	// Set when loading failed; drops late results until the next load starts.
	private boolean loadFailed;

	@Inject
	RenatusPanel(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	void init(RenatusPlugin plugin)
	{
		this.plugin = plugin;

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new DynamicGridLayout(0, 1, 0, 8));

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		JLabel title = new JLabel("Renatus PvM");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(GOLD);
		header.add(title, BorderLayout.WEST);
		refreshButton.setFocusable(false);
		refreshButton.addActionListener(e ->
		{
			plugin.refreshAll();
			startRefreshCooldown();
		});
		header.add(refreshButton, BorderLayout.EAST);
		add(header);

		messageLabel.setForeground(MUTED);
		messageLabel.setFont(FontManager.getRunescapeSmallFont());

		searchField.setIcon(IconTextField.Icon.SEARCH);
		searchField.setPreferredSize(new Dimension(PANEL_WIDTH - 20, 30));
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchField.setToolTipText("Look up a clan member");
		searchField.addActionListener(e -> submitSearch());
		searchField.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				updateSuggestions();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				updateSuggestions();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				updateSuggestions();
			}
		});
		searchField.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyPressed(KeyEvent e)
			{
				switch (e.getKeyCode())
				{
					case KeyEvent.VK_DOWN:
						selectSuggestion(selectedSuggestion + 1);
						e.consume();
						break;
					case KeyEvent.VK_UP:
						selectSuggestion(selectedSuggestion - 1);
						e.consume();
						break;
					case KeyEvent.VK_ESCAPE:
						hideSuggestions();
						break;
				}
			}
		});
		add(searchField);

		suggestionsPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		suggestionsPanel.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));

		profilePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		profilePanel.setBorder(new EmptyBorder(8, 8, 8, 8));
		add(profilePanel);

		clanPanel.setOpaque(false);
		add(section("Clan Details", clanPanel));

		JPanel tabDisplay = new JPanel(new BorderLayout());
		tabDisplay.setOpaque(false);
		MaterialTabGroup tabs = new MaterialTabGroup(tabDisplay);
		tabs.setLayout(new GridLayout(1, 3, 4, 4));
		MaterialTab leaderboardTab = new MaterialTab("Top", tabs, leaderboardList);
		tabs.addTab(leaderboardTab);
		tabs.addTab(new MaterialTab("Recent", tabs, recentList));
		tabs.addTab(new MaterialTab("Ranks", tabs, ranksList));
		tabs.select(leaderboardTab);
		add(section("Clan Activity", tabs, tabDisplay));

		for (JPanel list : new JPanel[]{leaderboardList, recentList, ranksList})
		{
			list.setOpaque(false);
		}

		renderProfile();
		showSetup(RenatusApiClient.SetupState.DISABLED);
	}

	// -- status messages ------------------------------------------------------

	void showSetup(RenatusApiClient.SetupState state)
	{
		if (state != RenatusApiClient.SetupState.READY)
		{
			clearData();
		}
		switch (state)
		{
			case DISABLED:
				showMessage("Enable \"Connect to clan server\" in the plugin config.");
				break;
			case NO_KEY:
				showMessage("Run /get-api-key in the Renatus Discord and paste the key into the plugin config.");
				break;
			default:
				clearMessage();
		}
	}

	void showMessage(String message)
	{
		messageLabel.setText("<html>" + escape(message) + "</html>");
		if (messageLabel.getParent() != this)
		{
			add(messageLabel, 1); // directly under the header
		}
		revalidate();
		repaint();
	}

	void clearMessage()
	{
		if (messageLabel.getParent() == this)
		{
			remove(messageLabel);
			revalidate();
			repaint();
		}
	}

	/** Disables the Refresh button for {@link #REFRESH_COOLDOWN_SECONDS}, counting down on it. */
	private void startRefreshCooldown()
	{
		stopRefreshCooldown();
		cooldownLeft = REFRESH_COOLDOWN_SECONDS;
		refreshButton.setEnabled(false);
		refreshButton.setText(refreshLabel(cooldownLeft));
		cooldownTimer = new Timer(1000, e ->
		{
			cooldownLeft--;
			if (cooldownLeft <= 0)
			{
				stopRefreshCooldown();
			}
			else
			{
				refreshButton.setText(refreshLabel(cooldownLeft));
			}
		});
		cooldownTimer.start();
	}

	/** Clears any running cooldown and re-enables the Refresh button. */
	void stopRefreshCooldown()
	{
		if (cooldownTimer != null)
		{
			cooldownTimer.stop();
			cooldownTimer = null;
		}
		cooldownLeft = 0;
		refreshButton.setEnabled(true);
		refreshButton.setText(refreshLabel(0));
	}

	private static String refreshLabel(int secondsLeft)
	{
		return secondsLeft > 0 ? String.valueOf(secondsLeft) : "Refresh";
	}

	// -- load state -----------------------------------------------------------

	/** Starts a fresh load: data from the server is accepted again. */
	void beginLoad()
	{
		loadFailed = false;
	}

	/**
	 * Loading data failed (bad API key, server down...): empty every section
	 * and show why. Results from the same load that arrive later are dropped
	 * so the panel doesn't half-fill.
	 */
	void loadFailed(String message)
	{
		loadFailed = true;
		clearData();
		showMessage(message);
	}

	/** Empties the profile, clan stats, and the leaderboard, recent and ranks tabs. */
	void clearData()
	{
		ownProfile = null;
		ownLoaded = false;
		lookupName = null;
		lookupProfile = null;
		ranks = Collections.emptyList();
		expandedSplits.clear();
		members = Collections.emptyList();
		searchField.setText("");
		hideSuggestions();

		clanPanel.removeAll();
		leaderboardList.removeAll();
		recentList.removeAll();
		renderProfile();
		renderRanks();
		revalidate();
		repaint();
	}

	// -- data setters ---------------------------------------------------------

	void setOwnProfile(@Nullable PlayerProfile profile)
	{
		if (loadFailed)
		{
			return;
		}
		ownProfile = profile;
		ownLoaded = true;
		if (lookupName == null)
		{
			renderProfile();
		}
	}

	void setLookupProfile(String name, @Nullable PlayerProfile profile)
	{
		lookupName = name;
		lookupProfile = profile;
		renderProfile();
	}

	void setClan(@Nullable ClanSummary clan)
	{
		if (loadFailed)
		{
			return;
		}
		clanPanel.removeAll();
		if (clan != null)
		{
			clanPanel.add(statBox("Members", Integer.toString(clan.getActiveMembers())));
			clanPanel.add(statBox("Total split", gp(clan.getTotalGp())));
			clanPanel.add(statBox("Splits this month", Integer.toString(clan.getSplitsThisMonth())));
			clanPanel.add(statBox("Last month", Integer.toString(clan.getSplitsLastMonth())));
			ranks = clan.getRanks() != null ? clan.getRanks() : Collections.emptyList();
			renderRanks();
		}
		revalidate();
		repaint();
	}

	void setLeaderboard(@Nullable List<LeaderboardEntry> entries)
	{
		if (loadFailed)
		{
			return;
		}
		leaderboardList.removeAll();
		if (entries != null)
		{
			int position = 1;
			for (LeaderboardEntry entry : entries)
			{
				String rank = entry.getRank() != null ? entry.getRank() + " · " : "";
				JPanel row = row(null,
					"#" + position++ + " " + entry.getRunescapeName(),
					rank + entry.getSplitCount() + " splits",
					gp(entry.getTotalGp()));
				clickToLookup(row, entry.getRunescapeName());
				leaderboardList.add(row);
			}
		}
		revalidate();
		repaint();
	}

	void setRecentSplits(@Nullable List<Split> splits)
	{
		if (loadFailed)
		{
			return;
		}
		recentList.removeAll();
		if (splits != null)
		{
			for (Split split : splits)
			{
				JPanel row = row(split.getItemId(), split.getItemName(), split.getRunescapeName(), gp(split.getValue()));
				clickToLookup(row, split.getRunescapeName());
				if (split.hasDetails())
				{
					row.setComponentPopupMenu(participantsMenu(split));
					for (Component child : row.getComponents())
					{
						((JComponent) child).setInheritsPopupMenu(true);
					}
					String lookupHint = Split.isLookupable(split.getRunescapeName())
						? "Look up " + split.getRunescapeName() + " - " : "";
					row.setToolTipText(lookupHint + "right-click for split details");
				}
				recentList.add(row);
			}
		}
		revalidate();
		repaint();
	}

	/** Clan member names offered as search suggestions. Null leaves the current list alone. */
	void setMembers(@Nullable List<String> names)
	{
		if (loadFailed || names == null)
		{
			return;
		}
		List<String> sorted = new ArrayList<>();
		for (String name : names)
		{
			if (name != null && !name.trim().isEmpty())
			{
				sorted.add(name);
			}
		}
		sorted.sort(String.CASE_INSENSITIVE_ORDER);
		members = sorted;
		updateSuggestions();
	}

	// -- search suggestions ---------------------------------------------------

	/** Enter in the search field: look up the highlighted suggestion, else what was typed. */
	private void submitSearch()
	{
		if (selectedSuggestion >= 0 && selectedSuggestion < suggestions.size())
		{
			lookup(suggestions.get(selectedSuggestion));
		}
		else
		{
			hideSuggestions();
			plugin.lookupPlayer(searchField.getText());
		}
	}

	/** Rebuilds the dropdown from the search text: names starting with it first, then names containing it. */
	private void updateSuggestions()
	{
		if (updatingSearch)
		{
			return;
		}
		String query = normalizeName(searchField.getText());
		suggestions.clear();
		if (!query.isEmpty())
		{
			List<String> contains = new ArrayList<>();
			for (String name : members)
			{
				String normalized = normalizeName(name);
				if (normalized.startsWith(query))
				{
					suggestions.add(name);
				}
				else if (normalized.contains(query))
				{
					contains.add(name);
				}
			}
			suggestions.addAll(contains);
			if (suggestions.size() > MAX_SUGGESTIONS)
			{
				suggestions.subList(MAX_SUGGESTIONS, suggestions.size()).clear();
			}
		}
		renderSuggestions();
	}

	private void hideSuggestions()
	{
		suggestions.clear();
		renderSuggestions();
	}

	private void renderSuggestions()
	{
		selectedSuggestion = -1;
		suggestionsPanel.removeAll();
		suggestionLabels.clear();

		if (suggestions.isEmpty())
		{
			if (suggestionsPanel.getParent() == this)
			{
				remove(suggestionsPanel);
			}
		}
		else
		{
			for (int i = 0; i < suggestions.size(); i++)
			{
				suggestionsPanel.add(suggestionLabel(suggestions.get(i), i));
			}
			if (suggestionsPanel.getParent() != this)
			{
				add(suggestionsPanel, getComponentZOrder(searchField) + 1); // directly under the search field
			}
		}
		revalidate();
		repaint();
	}

	private JLabel suggestionLabel(String name, int index)
	{
		JLabel label = new JLabel(name);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Color.WHITE);
		label.setOpaque(true);
		label.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		label.setBorder(new EmptyBorder(4, 8, 4, 8));
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					lookup(name);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				selectSuggestion(index);
			}
		});
		suggestionLabels.add(label);
		return label;
	}

	/** Highlights one suggestion (arrow keys / hover); out of range clears the highlight. */
	private void selectSuggestion(int index)
	{
		if (suggestions.isEmpty())
		{
			return;
		}
		selectedSuggestion = Math.max(-1, Math.min(index, suggestions.size() - 1));
		for (int i = 0; i < suggestionLabels.size(); i++)
		{
			boolean selected = i == selectedSuggestion;
			JLabel label = suggestionLabels.get(i);
			label.setBackground(selected ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			label.setForeground(selected ? GOLD : Color.WHITE);
		}
	}

	/** Lower-case, with _, - and non-breaking spaces treated as plain spaces, the way RSNs are written interchangeably. */
	private static String normalizeName(String name)
	{
		return name.replace('_', ' ').replace('-', ' ').replace(' ', ' ').trim().toLowerCase(Locale.ROOT);
	}

	// -- rendering ------------------------------------------------------------

	private void renderProfile()
	{
		profilePanel.removeAll();

		boolean lookup = lookupName != null;
		PlayerProfile profile = lookup ? lookupProfile : ownProfile;

		if (lookup)
		{
			JButton back = new JButton("Back to my profile");
			back.setFocusable(false);
			back.addActionListener(e ->
			{
				lookupName = null;
				lookupProfile = null;
				searchField.setText("");
				renderProfile();
			});
			profilePanel.add(back);
		}

		if (profile == null && !lookup)
		{
			profilePanel.add(muted(ownLoaded ? "Couldn't load your clan profile." : "Your clan profile will show here."));
		}
		else if (profile == null)
		{
			profilePanel.add(bold(lookupName, Color.WHITE));
			profilePanel.add(muted("Not on the Renatus roster."));
		}
		else
		{
			renderProfileBody(profile);
		}

		renderRanks();
		profilePanel.revalidate();
		profilePanel.repaint();
	}

	private void renderProfileBody(PlayerProfile profile)
	{
		String displayName = profile.getRunescapeName();
		if (profile.getRunescapeNameAlt() != null)
		{
			displayName += " | " + profile.getRunescapeNameAlt();
		}
		profilePanel.add(bold(displayName, Color.WHITE));

		if (!profile.isActive())
		{
			profilePanel.add(muted("Not an active clan member."));
			return;
		}

		Rank rank = profile.getRank();
		profilePanel.add(bold(rank != null ? rank.getName() : "Unranked", GOLD));

		JPanel stats = new JPanel(new GridLayout(0, 2, 4, 2));
		stats.setOpaque(false);
		stats.add(muted("Days in clan"));
		stats.add(value(Integer.toString(profile.getDaysInClan())));
		stats.add(muted("Total split"));
		stats.add(value(gp(profile.getTotalGp())));
		stats.add(muted("Approved splits"));
		stats.add(value(Integer.toString(profile.getSplitCount())));
		if (profile.getPendingSubmissions() > 0)
		{
			stats.add(muted("Awaiting approval"));
			stats.add(value(Integer.toString(profile.getPendingSubmissions())));
		}
		profilePanel.add(stats);

		Rank next = profile.getNextRank();
		if (next != null)
		{
			profilePanel.add(muted("Next rank: " + next.getName()));
			profilePanel.add(progress(profile.getTotalGp(), next.getGpRequired(),
				gp(profile.getTotalGp()), gp(next.getGpRequired()) + " gp"));
			if (next.getDaysRequired() > 0)
			{
				profilePanel.add(progress(profile.getDaysInClan(), next.getDaysRequired(),
					Integer.toString(profile.getDaysInClan()), next.getDaysRequired() + " days"));
			}
		}
		else
		{
			profilePanel.add(muted("Highest rank reached."));
		}

		if (!profile.getPendingConfirmations().isEmpty())
		{
			profilePanel.add(pendingBox(profile.getPendingConfirmations()));
		}

		if (!profile.getRecentSplits().isEmpty())
		{
			profilePanel.add(bold("Your Recent Splits", Color.WHITE));
			for (Split split : profile.getRecentSplits())
			{
				profilePanel.add(recentSplitEntry(split));
			}
		}
	}

	private void renderRanks()
	{
		ranksList.removeAll();
		PlayerProfile shown = lookupName != null ? lookupProfile : ownProfile;
		Rank currentRank = shown != null ? shown.getRank() : null;
		String current = currentRank != null ? currentRank.getName() : null;
		for (Rank rank : ranks)
		{
			// Ranks below the one shown are already behind them: list only the current rank and up.
			if (currentRank != null && isBelow(rank, currentRank))
			{
				continue;
			}
			String detail = gp(rank.getGpRequired()) + " gp · " + rank.getDaysRequired() + " days";
			JPanel row = row(null, rank.getName(), detail, "");
			if (rank.getName().equals(current))
			{
				row.setBorder(BorderFactory.createCompoundBorder(
					BorderFactory.createMatteBorder(0, 3, 0, 0, GOLD),
					new EmptyBorder(4, 5, 4, 6)));
			}
			ranksList.add(row);
		}
		ranksList.revalidate();
		ranksList.repaint();
	}

	/** Whether {@code rank} sits below {@code current}: lower gp requirement, or equal gp and fewer days. */
	private static boolean isBelow(Rank rank, Rank current)
	{
		if (rank.getName().equals(current.getName()))
		{
			return false;
		}
		if (rank.getGpRequired() != current.getGpRequired())
		{
			return rank.getGpRequired() < current.getGpRequired();
		}
		return rank.getDaysRequired() < current.getDaysRequired();
	}

	// -- component helpers ----------------------------------------------------

	/** Right-click menu on a pending split: confirm/deny or copy its code. */
	private JPopupMenu responseMenu(Split split, String code)
	{
		JPopupMenu menu = new JPopupMenu();

		JMenuItem confirm = new JMenuItem("Confirm split");
		confirm.addActionListener(e -> plugin.respondToSplit(split, true));
		menu.add(confirm);

		JMenuItem deny = new JMenuItem("Deny split");
		deny.addActionListener(e ->
		{
			int choice = JOptionPane.showConfirmDialog(this,
				"Deny the " + split.getItemName() + " split from " + split.getSubmitter() + "?\n"
					+ "You can't change your answer afterwards.",
				"Deny split " + code, JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
			if (choice == JOptionPane.YES_OPTION)
			{
				plugin.respondToSplit(split, false);
			}
		});
		menu.add(deny);

		menu.addSeparator();
		JMenuItem copy = new JMenuItem("Copy code");
		copy.addActionListener(e -> copyCode(code));
		menu.add(copy);
		return menu;
	}

	private void copyCode(String code)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(code), null);
		showMessage("Copied split code " + code);
	}

	private JPanel pendingBox(List<Split> splits)
	{
		JPanel box = new JPanel(new DynamicGridLayout(0, 1, 0, 3));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(PENDING_RED, 2),
			new EmptyBorder(5, 5, 5, 5)));
		box.add(bold("Waiting for confirmation (" + splits.size() + ")", PENDING_RED));

		for (Split split : splits)
		{
			String code = split.getCode() != null ? split.getCode() : "";
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setBackground(ColorScheme.DARK_GRAY_COLOR);
			row.setBorder(new EmptyBorder(4, 6, 4, 6));

			if (split.getItemId() != null && split.getItemId() > 1)
			{
				JLabel icon = new JLabel();
				icon.setPreferredSize(new Dimension(36, 32));
				itemManager.getImage(split.getItemId()).addTo(icon);
				row.add(icon, BorderLayout.WEST);
			}

			// participants is submitter first, then the tagged members
			List<String> participants = split.getParticipants();
			StringBuilder with = new StringBuilder();
			if (participants.size() > 1)
			{
				with.append("<br><font color='#a5a5a5'>with:");
				for (String name : participants.subList(1, participants.size()))
				{
					with.append("<br>&nbsp;&nbsp;- ").append(escape(name));
				}
				with.append("</font>");
			}
			long splitValue = split.effectiveSplitValue();
			String values = (splitValue > 0 ? "<br>Split Value: " + gp(splitValue) + " gp" : "")
				+ (split.showRawValue() ? "<br><font color='#a5a5a5'>Raw Value: " + gp(split.getRawValue()) + " gp</font>" : "");
			JLabel text = new JLabel("<html><body style='width:130px'>" + escape(split.getItemName())
				+ "<br><font color='#a5a5a5'>from " + escape(split.getSubmitter()) + "</font>"
				+ with
				+ values
				+ "<br><font color='#ffc83c'>Code: " + escape(code) + "</font></body></html>");
			text.setFont(FontManager.getRunescapeSmallFont());
			text.setForeground(Color.WHITE);
			row.add(text, BorderLayout.CENTER);

			if (!code.isEmpty())
			{
				row.setToolTipText("Right-click to confirm or deny - left-click to copy code " + code);
				row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				row.setComponentPopupMenu(responseMenu(split, code));
				for (Component child : row.getComponents())
				{
					((JComponent) child).setInheritsPopupMenu(true);
				}
				row.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mouseClicked(MouseEvent e)
					{
						if (!SwingUtilities.isLeftMouseButton(e))
						{
							return;
						}
						copyCode(code);
					}

					@Override
					public void mouseEntered(MouseEvent e)
					{
						row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
					}

					@Override
					public void mouseExited(MouseEvent e)
					{
						row.setBackground(ColorScheme.DARK_GRAY_COLOR);
					}
				});
			}
			box.add(row);
		}
		return box;
	}

	private JPanel row(@Nullable Integer itemId, String title, String subtitle, String right)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(4, 8, 4, 6));

		if (itemId != null && itemId > 1)
		{
			JLabel icon = new JLabel();
			icon.setPreferredSize(new Dimension(36, 32));
			itemManager.getImage(itemId).addTo(icon);
			row.add(icon, BorderLayout.WEST);
		}

		JLabel text = new JLabel("<html>" + escape(title) + "<br><font color='#a5a5a5'>" + escape(subtitle) + "</font></html>");
		text.setFont(FontManager.getRunescapeSmallFont());
		text.setForeground(Color.WHITE);
		row.add(text, BorderLayout.CENTER);

		if (!right.isEmpty())
		{
			JLabel value = new JLabel(right, SwingConstants.RIGHT);
			value.setFont(FontManager.getRunescapeSmallFont());
			value.setForeground(GOLD);
			row.add(value, BorderLayout.EAST);
		}
		return row;
	}

	/**
	 * "Your Recent Splits" row. When the server sends details, left-click
	 * toggles its values and participant list under the row.
	 */
	private JComponent recentSplitEntry(Split split)
	{
		JPanel row = row(split.getItemId(), split.getItemName(), date(split.getDate()), gp(split.getValue()));
		List<String> participants = split.getParticipants();
		if (!split.hasDetails())
		{
			return row;
		}

		String key = split.getCode() != null ? split.getCode() : split.getItemName() + "|" + split.getDate();
		boolean expanded = expandedSplits.contains(key);

		row.setToolTipText((expanded ? "Hide" : "Show") + " split details");
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (!SwingUtilities.isLeftMouseButton(e))
				{
					return;
				}
				if (!expandedSplits.remove(key))
				{
					expandedSplits.add(key);
				}
				renderProfile();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});

		if (!expanded)
		{
			return row;
		}

		JPanel entry = new JPanel(new DynamicGridLayout(0, 1, 0, 0));
		entry.setOpaque(false);
		entry.add(row);

		JPanel list = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		list.setBorder(new EmptyBorder(2, 16, 4, 6));

		JPanel values = new JPanel(new GridLayout(0, 2, 4, 1));
		values.setOpaque(false);
		long splitValue = split.effectiveSplitValue();
		if (splitValue > 0)
		{
			values.add(muted("Split Value"));
			values.add(value(gp(splitValue) + " gp"));
		}
		if (split.showRawValue())
		{
			values.add(muted("Raw Value"));
			values.add(value(gp(split.getRawValue()) + " gp"));
		}
		if (values.getComponentCount() > 0)
		{
			list.add(values);
		}

		if (!participants.isEmpty())
		{
			list.add(muted("In this split (" + participants.size() + ")"));
			for (int i = 0; i < participants.size(); i++)
			{
				list.add(participantLabel(participants.get(i), i == 0));
			}
		}
		entry.add(list);
		return entry;
	}

	/** clickable participant name to look them up unless they've left the clan. */
	private JLabel participantLabel(String name, boolean submitter)
	{
		JLabel label = new JLabel(displayName(name) + (submitter ? " (submitter)" : ""));
		label.setFont(FontManager.getRunescapeSmallFont());
		if (!Split.isLookupable(name))
		{
			label.setForeground(MUTED);
			label.setToolTipText("No longer in the clan");
			return label;
		}
		label.setForeground(Color.WHITE);
		label.setToolTipText("Look up " + name);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					lookup(name);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setForeground(GOLD);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setForeground(Color.WHITE);
			}
		});
		return label;
	}

	/**
	 * Right-click menu on a clan recent split: its values, then its participants;
	 * picking a participant looks them up.
	 */
	private JPopupMenu participantsMenu(Split split)
	{
		JPopupMenu menu = new JPopupMenu();
		long splitValue = split.effectiveSplitValue();
		if (splitValue > 0)
		{
			menu.add(infoItem("Split Value: " + gp(splitValue) + " gp"));
		}
		if (split.showRawValue())
		{
			menu.add(infoItem("Raw Value: " + gp(split.getRawValue()) + " gp"));
		}

		List<String> participants = split.getParticipants();
		if (participants.isEmpty())
		{
			return menu;
		}
		if (menu.getComponentCount() > 0)
		{
			menu.addSeparator();
		}
		menu.add(infoItem("In this split:"));
		for (int i = 0; i < participants.size(); i++)
		{
			String name = participants.get(i);
			JMenuItem item = new JMenuItem(displayName(name) + (i == 0 ? " (submitter)" : ""));
			if (Split.isLookupable(name))
			{
				item.addActionListener(e -> lookup(name));
			}
			else
			{
				item.setEnabled(false);
			}
			menu.add(item);
		}
		return menu;
	}

	/** A non-clickable menu line. */
	private static JMenuItem infoItem(String text)
	{
		JMenuItem item = new JMenuItem(text);
		item.setEnabled(false);
		return item;
	}

	private void lookup(String name)
	{
		updatingSearch = true;
		try
		{
			searchField.setText(name);
		}
		finally
		{
			updatingSearch = false;
		}
		hideSuggestions();
		plugin.lookupPlayer(name);
	}

	private static String displayName(String name)
	{
		return name == null || name.trim().isEmpty() ? Split.UNKNOWN_NAME : name;
	}

	private void clickToLookup(JPanel row, String name)
	{
		if (!Split.isLookupable(name))
		{
			return;
		}
		row.setToolTipText("Look up " + name);
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				// left-click only: right-click opens the participants menu
				if (SwingUtilities.isLeftMouseButton(e))
				{
					lookup(name);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
	}

	/** An outlined box with a gold title bar on top, holding the given components stacked vertically. */
	private static JComponent section(String title, JComponent... contents)
	{
		JPanel box = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		box.setOpaque(false);
		box.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(4, 6, 6, 6)));
		box.add(sectionDivider(title));
		for (JComponent content : contents)
		{
			box.add(content);
		}
		return box;
	}

	/** A titled gold bar heading a section. */
	private static JComponent sectionDivider(String text)
	{
		JPanel divider = new JPanel(new BorderLayout());
		divider.setOpaque(false);
		divider.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 2, 0, GOLD),
			new EmptyBorder(4, 2, 3, 2)));
		divider.add(bold(text, GOLD), BorderLayout.WEST);
		return divider;
	}

	private JComponent statBox(String label, String value)
	{
		JPanel box = new JPanel(new BorderLayout());
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(new EmptyBorder(4, 6, 4, 6));
		box.add(muted(label), BorderLayout.NORTH);
		box.add(value(value), BorderLayout.CENTER);
		return box;
	}

	/**
	 * ProgressBar lays its left/center/right labels out in three equal columns,
	 * so each label only gets a third of the width. Keep each one short:
	 * current on the left, percent in the middle, target on the right.
	 */
	private static ProgressBar progress(long current, long required, String left, String right)
	{
		ProgressBar bar = new ProgressBar();
		int percent = required <= 0 ? 100 : (int) Math.min(100, current * 100 / required);
		bar.setMaximumValue(100);
		bar.setValue(percent);
		bar.setLeftLabel(left);
		bar.setCenterLabel(percent + "%");
		bar.setRightLabel(right);
		bar.setForeground(percent >= 100 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR);
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setPreferredSize(new Dimension(PANEL_WIDTH - 36, 16));
		return bar;
	}

	private static JLabel bold(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(color);
		return label;
	}

	private static JLabel muted(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED);
		return label;
	}

	private static JLabel value(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Color.WHITE);
		return label;
	}

	private static String gp(long amount)
	{
		return QuantityFormatter.quantityToStackSize(amount);
	}

	private static String date(String iso)
	{
		return iso != null && iso.length() >= 10 ? iso.substring(0, 10) : "";
	}

	private static String escape(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.renatus;

import com.google.inject.Provides;
import com.renatus.model.PlayerProfile;
import com.renatus.model.Split;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.externalplugins.PluginHubManifest;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Renatus PvM",
	description = "Renatus clan companion: rank progress, splits and leaderboard",
	tags = {"renatus", "clan", "splits", "rank"}
)
public class RenatusPlugin extends Plugin
{
	private static final long REFRESH_MINUTES = 15;
	/** How often /me is polled while logged in, to catch newly tagged splits. Matches the server's cache TTL. */
	private static final long OWN_PROFILE_POLL = 5;
	private static final int RECENT_SPLITS = 5;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RenatusConfig config;

	@Inject
	private RenatusApiClient api;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Notifier notifier;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private ScheduledExecutorService executor;

	private RenatusPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> refreshTask;
	private ScheduledFuture<?> ownProfileTask;

	private Set<String> knownPendingCodes;
	private BufferedImage infoBoxImage;
	/** Only touched on the client thread. */
	private PendingSplitsInfoBox pendingInfoBox;
	/** Last pending-confirmation count from /me API; -1 until loaded. */
	private volatile int pendingCount = -1;

	private volatile boolean loginHandled;
	// The last data load failed and the panel was emptied; the next poll reloads everything.
	private volatile boolean loadFailed;
	private volatile boolean reminderDue;

	@Override
	protected void startUp()
	{
		panel = injector.getInstance(RenatusPanel.class);
		panel.init(this);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		infoBoxImage = ImageUtil.loadImageResource(getClass(), "infobox.png");
		navButton = NavigationButton.builder()
			.tooltip("Renatus PvM")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		executor.execute(this::refreshAll);
		refreshTask = executor.scheduleWithFixedDelay(() ->
		{
			if (loginHandled)
			{
				refreshAll();
			}
		}, REFRESH_MINUTES, REFRESH_MINUTES, TimeUnit.MINUTES);
		ownProfileTask = executor.scheduleWithFixedDelay(() ->
		{
			if (!loginHandled)
			{
				return;
			}
			if (loadFailed)
			{
				refreshAll();
			}
			else
			{
				refreshOwnProfile();
			}
		}, OWN_PROFILE_POLL, OWN_PROFILE_POLL, TimeUnit.MINUTES);
	}

	@Override
	protected void shutDown()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}
		if (ownProfileTask != null)
		{
			ownProfileTask.cancel(false);
			ownProfileTask = null;
		}
		knownPendingCodes = null;
		clientToolbar.removeNavigation(navButton);
		infoBoxManager.removeIf(PendingSplitsInfoBox.class::isInstance);
		pendingInfoBox = null;
		pendingCount = -1;
		navButton = null;
		RenatusPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::stopRefreshCooldown);
		}
		panel = null;
		loginHandled = false;
		reminderDue = false;
	}

	@Provides
	RenatusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RenatusConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			loginHandled = false;
			reminderDue = false;
			knownPendingCodes = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Treat the first tick with a local player as "just logged in", so the
		// pending-split reminder lands once the chatbox is ready.
		if (loginHandled)
		{
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null)
		{
			return;
		}
		loginHandled = true;
		reminderDue = true;
		refreshAll();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RenatusConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		clientThread.invokeLater(this::updateInfoBox);
		refreshAll();
	}

	/** Re-fetches everything. Safe to call from any thread. */
	void refreshAll()
	{
		RenatusPanel p = panel;
		if (p == null)
		{
			return;
		}

		RenatusApiClient.SetupState state = api.setupState();
		if (state != RenatusApiClient.SetupState.READY)
		{
			SwingUtilities.invokeLater(() -> p.showSetup(state));
			return;
		}
		loadFailed = false;
		SwingUtilities.invokeLater(() ->
		{
			p.beginLoad();
			p.clearMessage();
		});

		refreshOwnProfile();

		api.fetchClan(
			clan -> SwingUtilities.invokeLater(() -> p.setClan(clan)),
			this::loadError);
		api.fetchLeaderboard(config.leaderboardSize(),
			entries -> SwingUtilities.invokeLater(() -> p.setLeaderboard(entries)),
			this::loadError);
		api.fetchRecentSplits(RECENT_SPLITS,
			splits -> SwingUtilities.invokeLater(() -> p.setRecentSplits(splits)),
			this::loadError);
		// A failure won't  empty the panel.
		api.fetchMembers(
			names -> SwingUtilities.invokeLater(() -> p.setMembers(names)),
			error -> log.debug("Couldn't load clan member names: {}", error));
	}

	/**
	 * Confirms or denies a split from the panel's right-click menu. Discord is
	 * updated server-side (the bot rebuilds the embed), then the profile is
	 * re-fetched so the split drops out of the pending list.
	 */
	void respondToSplit(Split split, boolean approve)
	{
		RenatusPanel p = panel;
		if (p == null || split.getCode() == null || api.apiRoot() == null)
		{
			return;
		}
		String verb = approve ? "Confirmed" : "Denied";
		SwingUtilities.invokeLater(() -> p.showMessage((approve ? "Confirming " : "Denying ") + split.getItemName() + "..."));
		api.respondToSplit(split.getCode(), approve, result ->
		{
			String message = verb + " " + split.getItemName() + " from " + split.getSubmitter() + " (" + split.getCode() + ")"
				+ (result != null && result.isFinalized() ? ". Sent to staff for approval." : ".");
			SwingUtilities.invokeLater(() -> p.showMessage(message));
			refreshOwnProfile();
		}, this::showError);
	}

	/** Looks up any clan member by name and shows them in the panel. */
	void lookupPlayer(String rsn)
	{
		RenatusPanel p = panel;
		String name = Text.toJagexName(rsn);
		if (p == null || name.isEmpty() || api.apiRoot() == null)
		{
			return;
		}
		api.fetchPlayer(name,
			profile -> SwingUtilities.invokeLater(() -> p.setLookupProfile(name, profile)),
			this::showError);
	}

	private void refreshOwnProfile()
	{
		RenatusPanel p = panel;
		if (p == null || api.apiRoot() == null)
		{
			return;
		}
		// /me is resolved from the API key, so it works for any account the
		// member plays (main or alt) and even while logged out.
		api.fetchMe(profile ->
		{
			SwingUtilities.invokeLater(() -> p.setOwnProfile(profile));
			maybeRemindPending(profile);
			pendingCount = profile != null ? profile.getPendingConfirmations().size() : -1;
			clientThread.invokeLater(() ->
			{
				announceNewPending(profile);
				updateInfoBox();
			});
		}, this::loadError);
	}

	/**
	 * Posts a chat message for each split that started waiting on the player
	 * since the last /me result. The first result of a login only records
	 * what's already there (the login reminder covers those). Client thread only.
	 */
	private void announceNewPending(PlayerProfile profile)
	{
		if (profile == null)
		{
			return;
		}
		if (!loginHandled)
		{
			knownPendingCodes = null;
			return;
		}

		Set<String> current = new HashSet<>();
		for (Split split : profile.getPendingConfirmations())
		{
			if (split.getCode() != null)
			{
				current.add(split.getCode());
			}
		}

		Set<String> known = knownPendingCodes;
		knownPendingCodes = current;
		if (known == null || !config.newSplitAlert())
		{
			return;
		}

		for (Split split : profile.getPendingConfirmations())
		{
			if (split.getCode() == null || known.contains(split.getCode()))
			{
				continue;
			}
			String message = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append("[Renatus] ")
				.append(ChatColorType.NORMAL)
				.append("New split to confirm: ")
				.append(ChatColorType.HIGHLIGHT)
				.append(split.getItemName())
				.append(ChatColorType.NORMAL)
				.append(" from " + split.getSubmitter() + " (code " + split.getCode() + "). Confirm it in Discord.")
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(message)
				.build());
			notifier.notify("Renatus: new split to confirm - " + split.getItemName() + " from " + split.getSubmitter());
		}
	}

	/** Adds, updates or removes the pending-splits info box. Client thread only. */
	private void updateInfoBox()
	{
		int count = pendingCount;
		boolean show = config.pendingInfoBox() && count > 0 && api.apiRoot() != null;
		if (!show)
		{
			if (pendingInfoBox != null)
			{
				infoBoxManager.removeInfoBox(pendingInfoBox);
				pendingInfoBox = null;
			}
			return;
		}
		if (pendingInfoBox == null)
		{
			pendingInfoBox = new PendingSplitsInfoBox(infoBoxImage, this, count);
			infoBoxManager.addInfoBox(pendingInfoBox);
		}
		else
		{
			pendingInfoBox.setCount(count);
		}
	}

	private void maybeRemindPending(PlayerProfile profile)
	{
		if (!reminderDue)
		{
			return;
		}
		reminderDue = false;
		if (profile == null || !config.pendingReminder())
		{
			return;
		}

		int pending = profile.getPendingConfirmations().size();
		if (pending == 0)
		{
			return;
		}

		String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[Renatus] ")
			.append(ChatColorType.NORMAL)
			.append("You have ")
			.append(ChatColorType.HIGHLIGHT)
			.append(Integer.toString(pending))
			.append(ChatColorType.NORMAL)
			.append(pending == 1 ? " split" : " splits")
			.append(" waiting for your confirmation in Discord.")
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/** A one-off action (split response, lookup) failed: just show why. */
	private void showError(String message)
	{
		RenatusPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.showMessage(message));
		}
	}

	/**
	 * Loading the panel's data failed (bad API key, server down...): empty
	 * the panel and pending info box so nothing stale is shown.
	 */
	private void loadError(String message)
	{
		if (api.isRateLimited())
		{
			showError(message);
			return;
		}
		loadFailed = true;
		pendingCount = -1;
		clientThread.invokeLater(this::updateInfoBox);
		RenatusPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.loadFailed(message));
		}
	}

	static String getPluginVersion()
	{
		PluginHubManifest.DisplayData displayData = ExternalPluginManager.getDisplayData(RenatusPlugin.class);
		if (displayData != null && displayData.getVersion() != null)
		{
			return displayData.getVersion();
		}
		return "DEV";
	}
}

